    steps:
      - uses: actions/checkout@v6

      - uses: actions/setup-node@v6
        with:
          node-version: "24"
          cache: "npm"

      - uses: jdx/mise-action@v4
        with:
          install: false

      - name: Install pi
        run: |
          PI_VERSION="$(node -p 'require("./package.json").devDependencies["@earendil-works/pi-coding-agent"]')"
          npm install -g "@earendil-works/pi-coding-agent@$PI_VERSION"

      - name: Run bootstrap script
        run: ./scripts/install.sh

      - name: Run repository lint
        run: mise run lint

      - name: Show installed pi packages
        run: pi list

HK CONFIG
amends "package://github.com/jdx/hk/releases/download/v1.38.0/hk@1.38.0#/Config.pkl"
import "package://github.com/jdx/hk/releases/download/v1.38.0/hk@1.38.0#/Builtins.pkl"

hooks {
    ["pre-push"] {
        steps {
            ["prevent-fixup-merge"] {
                check = "scripts/prevent-fixup-merge.sh pre-push"
            }
        }
    }

    ["pre-merge-commit"] {
        steps {
            ["prevent-fixup-merge"] {
                check = "scripts/prevent-fixup-merge.sh"
            }
        }
    }

    ["pre-commit"] {
        fix = true
        stash = "git"
        steps {
            ["markdownlint-cli2"] {
                glob = List("**/*.md")
                check = "markdownlint-cli2 {{files}}"
                fix = "markdownlint-cli2 --fix {{files}}"
            }
            ["yamllint"] {
                glob = List("**/*.yml", "**/*.yaml")
                check = "yamllint -c .yamllint.yaml {{files}}"
            }
            ["check-added-large-files"] = Builtins.check_added_large_files
            ["check-case-conflict"] = Builtins.check_case_conflict
            ["check-executables-have-shebangs"] = Builtins.check_executables_have_shebangs
            ["check-merge-conflict"] = Builtins.check_merge_conflict
            ["check-symlinks"] = Builtins.check_symlinks
            ["detect-private-key"] = Builtins.detect_private_key
            ["mixed-line-ending"] = Builtins.mixed_line_ending
            ["no-commit-to-branch"] = (Builtins.no_commit_to_branch) {
                check = "hk util no-commit-to-branch --branch main"
            }
            ["trailing-whitespace"] = Builtins.trailing_whitespace
            ["end-of-file-fixer"] = Builtins.newlines
        }
    }
}

