	if (!ctx.hasUI) {
		await checkLabels(pi, ctx, repo);
		return;
	}

	const choice = await ctx.ui.select("Pac workflow setup", ["Labels: check (dry-run)", "Labels: apply changes", "Help"]);
	if (!choice) {
		ctx.ui.notify("Pac workflow setup cancelled", "info");
